1	import { runScenario, type Scenario } from "./claim-office.js";
2	
3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
6	
7	  return Buffer.concat(chunks).toString("utf8");
8	};
9	
10	const REJECTED = 1;
11	
12	try {
13	  const scenario = JSON.parse(await readStdin()) as Scenario;
14	
15	  process.stdout.write(JSON.stringify(runScenario(scenario)));
16	} catch (error) {
17	  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
18	  process.exit(REJECTED);
19	}
