10	describe("claim-office CLI", () => {
11	  it("reads a JSON scenario from stdin and writes the results JSON to stdout", () => {
12	    const stdout = runCli({
13	      customer: { yearsWithMHPCO: 5 },
14	      steps: [
15	        {
16	          op: "quote",
17	          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
18	        },
19	        {
20	          op: "claim",
21	          policy: 0,
22	          incident: { cause: "fire", damages: [{ itemType: "amulet", amount: 200 }] },
23	        },
24	      ],
25	    });
26	
27	    // 60 base - 12 loyalty + 6 first insurance + 5 fee = 59; cap 2 x 600 = 1200
28	    expect(JSON.parse(stdout)).toEqual({
29	      results: [{ premium: 59 }, { payout: 100, remainingCap: 1100 }],
30	    });
31	  });
32	
33	  it("on an invalid scenario exits with a non-zero status code, writes to stderr, and writes no results to stdout", () => {
34	    const result = spawnSync("npx", ["tsx", "src/cli.ts"], {
35	      input: JSON.stringify({
36	        customer: { yearsWithMHPCO: 0 },
37	        steps: [{ op: "quote", items: [{ type: "broomstick" }] }],
38	      }),
39	      encoding: "utf8",
40	    });
41	
42	    expect(result.status).not.toBe(0);
43	    expect(result.status).not.toBeNull();
44	    expect(result.stdout).not.toContain("results");
45	
46	    // a description of the problem, not a stack trace
47	    expect(result.stderr).toContain("the MHPCO price list does not cover a broomstick");
48	    expect(result.stderr).not.toContain("    at ");
49	  });
50	});
